import React from 'react';
import { render, screen } from '@testing-library/react';
import { Radio } from '../..';

const { Root, Item } = Radio;

describe('Radio', () => {
  it('should render', () => {
    render(
      <Radio.Root>
        <Radio.Item label="Label 1" id="item1" />
        <Radio.Item label="Label 2" id="item2" />
      </Radio.Root>
    );
    expect(screen.getByText('Label 1')).toBeInTheDocument();
    expect(screen.getByText('Label 2')).toBeInTheDocument();
  });

  it('should render with errorMessage', () => {
    render(
      <Root data-testid="radioGroup" error errorMessage="Error message">
        <Item label="Label 1" id="item1" />
        <Item label="Label 2" id="item2" />
      </Root>
    );
    expect(screen.getByText('Error message')).toBeInTheDocument();
    expect(screen.getByTestId('radioGroup')).toHaveErrorMessage('Error message');
  });
});
